<script setup>
import { computed } from 'vue'
import { state } from '../data/store'
const avgWaste = computed(()=> (state.categoryTrends.reduce((s,c)=>s+c.waste,0)/state.categoryTrends.length).toFixed(1))
const highestWaste = computed(()=> [...state.categoryTrends].sort((a,b)=>b.waste-a.waste)[0])
const potentialSavings = computed(()=> Math.round(state.categoryTrends.reduce((s,c)=>s+(c.spend*(c.waste/100)),0)))
</script>
<template>
  <div class="p-5 lg:p-8"><div><h2 class="text-2xl font-black">Food Cost & Waste Intelligence</h2><p class="mt-1 text-sm text-slate-500">Price movement, category spend and potential waste signals for HoReCa purchasing teams.</p></div>
    <section class="mt-6 grid gap-4 md:grid-cols-3"><div class="rounded-2xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500">Average Waste Rate</p><p class="mt-3 text-2xl font-black">{{ avgWaste }}%</p></div><div class="rounded-2xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500">Highest Waste Category</p><p class="mt-3 text-2xl font-black text-orange-500">{{ highestWaste.category }}</p><p class="mt-2 text-xs text-slate-400">{{ highestWaste.waste }}% estimated waste</p></div><div class="rounded-2xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500">Recoverable Cost Signal</p><p class="mt-3 text-2xl font-black text-emerald-600">OMR {{ potentialSavings }}</p><p class="mt-2 text-xs text-slate-400">Illustrative monthly waste value</p></div></section>
    <section class="mt-6 overflow-hidden rounded-2xl border border-slate-200 bg-white"><div class="border-b border-slate-100 p-6"><h3 class="font-bold">Category Intelligence</h3><p class="mt-1 text-xs text-slate-500">Price change and waste signals side by side.</p></div><div class="overflow-x-auto"><table class="w-full min-w-[760px]"><thead class="bg-slate-50 text-[10px] uppercase text-slate-400"><tr><th class="px-5 py-3 text-left">Category</th><th class="px-5 py-3 text-left">Spend</th><th class="px-5 py-3 text-left">Price movement</th><th class="px-5 py-3 text-left">Waste rate</th><th class="px-5 py-3 text-left">Recommended action</th></tr></thead><tbody><tr v-for="c in state.categoryTrends" :key="c.category" class="border-t border-slate-100"><td class="px-5 py-4 text-xs font-bold">{{ c.category }}</td><td class="px-5 py-4 text-xs">OMR {{ c.spend.toLocaleString() }}</td><td class="px-5 py-4 text-xs font-bold" :class="c.change<0?'text-emerald-600':'text-red-500'">{{ c.change>0?'+':'' }}{{ c.change }}%</td><td class="px-5 py-4 text-xs">{{ c.waste }}%</td><td class="px-5 py-4 text-xs text-slate-500">{{ c.waste>4?'Reduce order quantity / transfer stock':c.change<0?'Consider bringing purchase forward':'Monitor consumption and supplier pricing' }}</td></tr></tbody></table></div></section>
    <section class="mt-6 grid gap-5 xl:grid-cols-2"><div class="rounded-2xl bg-gradient-to-br from-[#1595B6] to-[#087391] p-6 text-white"><h3 class="font-bold">Smart Purchasing Recommendation</h3><p class="mt-4 text-sm leading-6 text-white/80">Fresh Produce is currently trending lower in price. If consumption forecasts remain stable, bringing forward part of next week’s purchase could reduce cost while maintaining stock coverage.</p><div class="mt-5 rounded-xl bg-white/10 p-4"><p class="text-xs text-white/60">Illustrative opportunity</p><p class="mt-2 text-xl font-black">Save ~OMR 310</p></div></div><div class="rounded-2xl border border-slate-200 bg-white p-6"><h3 class="font-bold">Waste Prevention</h3><p class="mt-1 text-xs text-slate-500">Use expiry and demand data before reordering perishables.</p><div class="mt-4 space-y-3"><div v-for="i in state.inventory.filter(x=>x.expiryDays<=7)" :key="i.id" class="rounded-xl bg-red-50/50 p-4"><div class="flex justify-between"><p class="text-sm font-bold">{{ i.product }}</p><span class="text-xs font-black text-red-500">{{ i.expiryDays }} days</span></div><p class="mt-2 text-xs text-slate-500">Consider menu promotion, stock transfer or a smaller next order.</p></div></div></div></section>
  </div>
</template>
